from collections import Counter, deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for ny, nx in ((y - 1, x), (y + 1, x), (y, x - 1), (y, x + 1)):
                    if (0 <= ny < h and 0 <= nx < w and (ny, nx) not in seen
                            and grid[ny][nx] == color):
                        seen.add((ny, nx))
                        q.append((ny, nx))
            ys = [y for y, _ in cells]
            xs = [x for _, x in cells]
            top, bottom, left, right = min(ys), max(ys), min(xs), max(xs)
            area = (bottom - top + 1) * (right - left + 1)
            if len(cells) >= 3 and len(cells) / area >= 0.70:
                objects.append((color, top, bottom, left, right, cells))

    palette = {obj[0] for obj in objects}
    out = [[bg for _ in range(w)] for _ in range(h)]
    for r in range(h):
        for c in range(w):
            if grid[r][c] in palette:
                out[r][c] = grid[r][c]
    for color, top, bottom, left, right, _ in objects:
        for r in range(top, bottom + 1):
            for c in range(left, right + 1):
                out[r][c] = color
    return out


if __name__ == '__main__':
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin))))
